do $$
declare src text := 'https://meslek.meb.gov.tr/upload/cop9_mem/2021_makine_mem_cop.pdf';
begin
insert into course_catalog(name,category,active)
select x,'uygulama',true from unnest(array['Makine Meslek Bilgisi','Teknik Resim','Bilgisayar Destekli Çizim','Ahilik Kültürü ve Girişimcilik','Temel İmalat İşlemleri','İmalat İşlemleri','Makine Meslek Resmi','Bilgisayar Kontrollü Tezgâhlarla Üretim (CNC)','Hidrolik Pnömatik','Bilgisayar Destekli Tasarım ve Üretim (CAD/CAM)','Sac Metal Kalıpları','Kalıp Meslek Resmi','Hacim Kalıpları','Kalıplama Teknikleri','İş Kalıpları','İş Etüdü ve Kalite Kontrol','İmalat Yöntemleri','Bakım Onarım Meslek Resmi','Temel Elektrik','Mekanik Bakım Onarım','Otomatik Kontrol Sistemleri','Mekanizmalar','Makine Elemanları ve Mekanizmalar','Seri Üretim Sistemleri ve Mekanizmalar','Tasarı Geometri','Katı Modelleme ve Animasyon','Cisimlerin Dayanımı','Tesisat Çizimleri','Mermer İmalat Teknikleri','Mozaik Eskitme','Mermer Meslek Resmi','Mermer Plaka İmalatı','Mermer Ocakçılığı','Seri Üretim Modellemeleri','Plastik Modellemeler','Maçalı Modellemeler','Hassas Döküm Modellemeleri','Değirmen Makineleri','Öğütme Teknolojisi','AR-GE ve Kalite Kontrol','Temel El İşlemleri','Temel Anahtarcılık','Kilit İşlemleri','İleri Anahtarcılık','Ofis Programları','Masa, Duvar ve Kurmalı Saatlerin Tamiri','Mekanik Kol Saatlerinin Tamiri','Elektromekanik ve Dijital Kol Saatleri Tamiri','Kinetik ve Fonksiyonlu Saatlerin Bakım ve Onarımı']::text[]) x where not exists(select 1 from course_catalog c where c.name=x);
with branches(branch_name,page) as (values ('Bilgisayarlı Makine İmalatı',9),('Endüstriyel Kalıp',10),('Makine Bakım Onarım',11),('Bilgisayar Destekli Makine Ressamlığı',12),('Mermer İşleme',13),('Bilgisayar Destekli Endüstriyel Modelleme',14),('Değirmencilik',15),('Anahtarcılık ve Çilingirlik',16),('Saat Tamirciliği',17))
insert into official_curriculum_profiles(id,effective_academic_year,school_type,school_subtype,program_type,field_name,branch_name,grade_level,required_course_count,required_hour_total,elective_course_min,elective_course_max,elective_hour_min,elective_hour_max,total_hour_min,total_hour_max,total_hour_target,group_rules,source_file_name,source_decision_no,source_note,active,schedule_variant,common_hours,vocational_hours,elective_vocational_hours,elective_hours,guidance_hours,enterprise_hours,applicability_status,source_page,parsed_constraints,academic_support_hours)
select gen_random_uuid(),p.effective_academic_year,p.school_type,p.school_subtype,p.program_type,'Makine Teknolojisi',b.branch_name,p.grade_level,p.required_course_count,p.required_hour_total,p.elective_course_min,p.elective_course_max,p.elective_hour_min,p.elective_hour_max,p.total_hour_min,p.total_hour_max,p.total_hour_target,p.group_rules,src,'2021-33','2021-33 yaşayan MESEM Makine Teknolojisi çizelgesi; parantezli temel ders saatleri DIPLOMA fark dersidir.',true,p.schedule_variant,p.common_hours,p.vocational_hours,p.elective_vocational_hours,p.elective_hours,p.guidance_hours,p.enterprise_hours,'CURRENTLY_VALID',b.page,p.parsed_constraints,p.academic_support_hours from official_curriculum_profiles p cross join branches b where p.active and p.school_type='MESEM' and p.field_name='Kuyumculuk Teknolojisi' and p.branch_name='Takı İmalatı' and not exists(select 1 from official_curriculum_profiles q where q.active and q.school_type='MESEM' and q.field_name='Makine Teknolojisi' and q.branch_name=b.branch_name and q.grade_level=p.grade_level and q.schedule_variant=p.schedule_variant);
with branches(branch_name,page) as (values ('Bilgisayarlı Makine İmalatı',9),('Endüstriyel Kalıp',10),('Makine Bakım Onarım',11),('Bilgisayar Destekli Makine Ressamlığı',12),('Mermer İşleme',13),('Bilgisayar Destekli Endüstriyel Modelleme',14),('Değirmencilik',15),('Anahtarcılık ve Çilingirlik',16),('Saat Tamirciliği',17)), base as (select s.*,c.name from official_course_schedule_catalog s join course_catalog c on c.id=s.course_id where s.active and s.school_type='MESEM' and s.field_name='Kuyumculuk Teknolojisi' and s.branch_name='Takı İmalatı' and (s.category='zorunlu' or c.name='İşletmelerde Mesleki Eğitim'))
insert into official_course_schedule_catalog(id,effective_academic_year,school_type,program_type,grade_level,course_id,category,hour_options,max_selections,repeat_across_years,elective_group_key,source_file_name,source_note,active,field_name,branch_name,parsed_constraints,school_subtype,source_decision_no,source_decision_date,source_page,source_section,parser_confidence,needs_review,schedule_variant)
select gen_random_uuid(),x.effective_academic_year,x.school_type,x.program_type,x.grade_level,x.course_id,x.category,x.hour_options,x.max_selections,x.repeat_across_years,x.elective_group_key,src,'Makine Teknolojisi 2021-33; temel/diploma fark dersleri ve İME doğrulanmış MESEM şablonundan.',true,'Makine Teknolojisi',b.branch_name,x.parsed_constraints,x.school_subtype,'2021-33',x.source_decision_date,b.page,x.source_section,1,false,x.schedule_variant from base x cross join branches b where not exists(select 1 from official_course_schedule_catalog q where q.active and q.school_type='MESEM' and q.field_name='Makine Teknolojisi' and q.branch_name=b.branch_name and q.grade_level=x.grade_level and q.schedule_variant=x.schedule_variant and q.course_id=x.course_id);
with v(branch_name,grade_level,course_name,hours) as (values ('Bilgisayarlı Makine İmalatı',9,'Makine Meslek Bilgisi',2),('Bilgisayarlı Makine İmalatı',10,'Teknik Resim',2),('Bilgisayarlı Makine İmalatı',10,'Temel İmalat İşlemleri',2),('Bilgisayarlı Makine İmalatı',11,'Bilgisayar Destekli Çizim',1),('Bilgisayarlı Makine İmalatı',11,'İmalat İşlemleri',4),('Bilgisayarlı Makine İmalatı',11,'Makine Meslek Resmi',2),('Bilgisayarlı Makine İmalatı',12,'Ahilik Kültürü ve Girişimcilik',1),('Bilgisayarlı Makine İmalatı',12,'Bilgisayar Kontrollü Tezgâhlarla Üretim (CNC)',4),('Bilgisayarlı Makine İmalatı',12,'Hidrolik Pnömatik',1),('Bilgisayarlı Makine İmalatı',12,'Bilgisayar Destekli Tasarım ve Üretim (CAD/CAM)',2),('Endüstriyel Kalıp',9,'Makine Meslek Bilgisi',2),('Endüstriyel Kalıp',10,'Teknik Resim',2),('Endüstriyel Kalıp',10,'Temel İmalat İşlemleri',2),('Endüstriyel Kalıp',11,'Bilgisayar Destekli Çizim',1),('Endüstriyel Kalıp',11,'Sac Metal Kalıpları',4),('Endüstriyel Kalıp',11,'Kalıp Meslek Resmi',2),('Endüstriyel Kalıp',12,'Ahilik Kültürü ve Girişimcilik',1),('Endüstriyel Kalıp',12,'Hacim Kalıpları',2),('Endüstriyel Kalıp',12,'Kalıplama Teknikleri',2),('Endüstriyel Kalıp',12,'İş Kalıpları',2),('Endüstriyel Kalıp',12,'İş Etüdü ve Kalite Kontrol',1),('Makine Bakım Onarım',9,'Makine Meslek Bilgisi',2),('Makine Bakım Onarım',10,'Teknik Resim',2),('Makine Bakım Onarım',10,'Temel İmalat İşlemleri',2),('Makine Bakım Onarım',11,'Bilgisayar Destekli Çizim',1),('Makine Bakım Onarım',11,'İmalat Yöntemleri',3),('Makine Bakım Onarım',11,'Bakım Onarım Meslek Resmi',2),('Makine Bakım Onarım',11,'Temel Elektrik',1),('Makine Bakım Onarım',12,'Ahilik Kültürü ve Girişimcilik',1),('Makine Bakım Onarım',12,'Mekanik Bakım Onarım',3),('Makine Bakım Onarım',12,'Otomatik Kontrol Sistemleri',2),('Makine Bakım Onarım',12,'Mekanizmalar',2),('Bilgisayar Destekli Makine Ressamlığı',9,'Makine Meslek Bilgisi',2),('Bilgisayar Destekli Makine Ressamlığı',10,'Teknik Resim',2),('Bilgisayar Destekli Makine Ressamlığı',10,'Temel İmalat İşlemleri',2),('Bilgisayar Destekli Makine Ressamlığı',11,'Bilgisayar Destekli Çizim',1),('Bilgisayar Destekli Makine Ressamlığı',11,'Makine Elemanları ve Mekanizmalar',3),('Bilgisayar Destekli Makine Ressamlığı',11,'Seri Üretim Sistemleri ve Mekanizmalar',3),('Bilgisayar Destekli Makine Ressamlığı',12,'Ahilik Kültürü ve Girişimcilik',1),('Bilgisayar Destekli Makine Ressamlığı',12,'Tasarı Geometri',2),('Bilgisayar Destekli Makine Ressamlığı',12,'Katı Modelleme ve Animasyon',2),('Bilgisayar Destekli Makine Ressamlığı',12,'Cisimlerin Dayanımı',2),('Bilgisayar Destekli Makine Ressamlığı',12,'Tesisat Çizimleri',1),('Mermer İşleme',9,'Makine Meslek Bilgisi',2),('Mermer İşleme',10,'Teknik Resim',2),('Mermer İşleme',10,'Temel İmalat İşlemleri',2),('Mermer İşleme',11,'Bilgisayar Destekli Çizim',1),('Mermer İşleme',11,'Mermer İmalat Teknikleri',3),('Mermer İşleme',11,'Mozaik Eskitme',2),('Mermer İşleme',11,'Mermer Meslek Resmi',1),('Mermer İşleme',12,'Ahilik Kültürü ve Girişimcilik',1),('Mermer İşleme',12,'Mermer Plaka İmalatı',4),('Mermer İşleme',12,'Mermer Ocakçılığı',2),('Mermer İşleme',12,'İş Etüdü ve Kalite Kontrol',1),('Bilgisayar Destekli Endüstriyel Modelleme',9,'Makine Meslek Bilgisi',2),('Bilgisayar Destekli Endüstriyel Modelleme',10,'Teknik Resim',2),('Bilgisayar Destekli Endüstriyel Modelleme',10,'Temel İmalat İşlemleri',2),('Bilgisayar Destekli Endüstriyel Modelleme',11,'Bilgisayar Destekli Çizim',1),('Bilgisayar Destekli Endüstriyel Modelleme',11,'Seri Üretim Modellemeleri',4),('Bilgisayar Destekli Endüstriyel Modelleme',11,'Plastik Modellemeler',2),('Bilgisayar Destekli Endüstriyel Modelleme',12,'Ahilik Kültürü ve Girişimcilik',1),('Bilgisayar Destekli Endüstriyel Modelleme',12,'Maçalı Modellemeler',4),('Bilgisayar Destekli Endüstriyel Modelleme',12,'Hassas Döküm Modellemeleri',3),('Değirmencilik',9,'Makine Meslek Bilgisi',2),('Değirmencilik',10,'Teknik Resim',2),('Değirmencilik',10,'Temel İmalat İşlemleri',2),('Değirmencilik',11,'