insert into official_course_schedule_catalog(id,effective_academic_year,school_type,program_type,grade_level,course_id,category,hour_options,max_selections,repeat_across_years,source_file_name,source_note,active,field_name,branch_name,parsed_constraints,source_decision_no,source_page,parser_confidence,needs_review,schedule_variant)
select gen_random_uuid(),'2026-2027','MESEM','MESEM',v.grade_level,c.id,'uygulama',array[v.hours]::smallint[],1,false,src,'2021-33 Makine Teknolojisi resmi haftalık ders çizelgesi.',true,'Makine Teknolojisi',v.branch_name,'{}'::jsonb,'2021-33',p.page,1,false,s.variant from v join course_catalog c on c.name=v.course_name join pages p on p.branch_name=v.branch_name cross join (values('USTALIK'),('DIPLOMA')) s(variant) where not exists(select 1 from official_course_schedule_catalog q where q.active and q.school_type='MESEM' and q.field_name='Makine Teknolojisi' and q.branch_name=v.branch_name and q.grade_level=v.grade_level and q.schedule_variant=s.variant and q.course_id=c.id);
end $$;